// ── Helpers: find todo by id ────────────────────────────────────────

function findTodoById(id) {
  for (var i = 0; i < todos.length; i++) {
    if (todos[i].id === id) return todos[i];
  }
  return null;
}

/**
 * @planks("the app is loaded")
 */
function setupEventDelegation() {
  // Toggle / Destroy / Dblclick via click+dblclick delegation
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest ? e.target.closest('li') : null;
    if (!li || !li.dataset.todoId) return;
    var todo = findTodoById(li.dataset.todoId);
    if (!todo) return;

    if (e.target.classList.contains('toggle')) {
      todo.completed = e.target.checked;
      todo.editing = false;
      setTodos(todos);
      render();
    } else if (e.target.classList.contains('destroy')) {
      todos = todos.filter(function (t) { return t !== todo; });
      setTodos(todos);
      render();
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest ? e.target.closest('label') : null;
    if (!label) return;
    var li = label.closest ? label.closest('li') : null;
    if (!li || !li.dataset.todoId) return;
    var todo = findTodoById(li.dataset.todoId);
    if (!todo) return;
    todo.editing = true;
    render();
    var editInput = li.querySelector('.edit');
    editInput.focus();
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  });

  // Edit keydown delegation
  todoList.addEventListener('keydown', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest ? e.target.closest('li') : null;
    if (!li || !li.dataset.todoId) return;
    var todo = findTodoById(li.dataset.todoId);
    if (!todo) return;
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      commitEdit(li, todo);
    } else if (e.keyCode === ESCAPE_KEY) {
      todo.editing = false;
      setTodos(todos);
      render();
    }
  });

  // Edit blur delegation (use capture for reliable blur from .edit)
  todoList.addEventListener('blur', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest ? e.target.closest('li') : null;
    if (!li || !li.dataset.todoId) return;
    var todo = findTodoById(li.dataset.todoId);
    if (!todo) return;
    commitEdit(li, todo);
  }, true);
}

// ── Init ───────────────────────────────────────────────────────────────

function init() {
  newTodoInput = qs('.new-todo');
  todoList = qs('.todo-list');
  mainSection = qs('.main');
  footerSection = qs('.footer');
  todoCount = qs('.todo-count');
  clearCompleted = qs('.clear-completed');
  toggleAll = qs('.toggle-all');
  filterLinks = qsa('.filters a');

  todos = getTodos();

  setupEventDelegation();

  // New todo: Enter to add
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Toggle all
  toggleAll.addEventListener('click', toggleAllTodos);

  // Clear completed
  clearCompleted.addEventListener('click', clearCompletedTodos);

  // Routing
  window.addEventListener('hashchange', route);

  render();
  newTodoInput.focus();
}

